/* 0080: list an objective's stock entries that hold an amount. */
uint8_t opeu_list_objective_stocks(uint8_t ds[65536], HostEvent event,
                                   uint16_t sp, OBJECTIVE_P objective) {
  uint8_t a, b;
  STOCK_P c;
  VW_USE();
  for (c = OBJECTIVE_STOCKS(objective), b = a = 0; b < 6; NEXT_STOCK(c), b++)
    if (STOCK_AMOUNT(c))
      SET_VIEW_STOCK(a++, c);
  return a;
}

/* 00c4: total amount and count of a regiment's flag-2 elements of a kind. */
uint16_t opeu_element_kind_total(uint8_t ds[65536], HostEvent event,
                                 uint16_t sp, ELEMENT_P unit, uint8_t kind,
                                 COUNT_P count) {
  ELEMENT_P a;
  uint16_t  b;
  VW_USE();
  CLEAR_COUNT(count);
  for (b = 0, a = ELEMENT_NEXT(unit); a; a = ELEMENT_NEXT(a))
    if (ELEMENT_KIND(a) == kind && (ELEMENT_FLAGS(a) & 2)) {
      b += ELEMENT_AMOUNT(a);
      BUMP_COUNT(count);
    }
  return b;
}

/* 0120: row check: own objectives must be eligible, others flagged 0x40. */
uint8_t opeu_view_objective_ok(uint8_t ds[65536], HostEvent event,
                               uint16_t sp) {
  OBJECTIVE_P a;
  uint8_t     b;
  VW_USE();
  a = VIEW_OBJECTIVE(ROW);
  b = OBJECTIVE_SIDE(a);
  if ((b == CURRENT && OBJECTIVE_ELIGIBLE(a)) ||
      (b != CURRENT && (OBJECTIVE_FLAGS(a) & 0x40)))
    return 1;
  return 0;
}

